package com.example.starter.dr;

import org.springframework.http.HttpStatus;

/**
 * 需求响应业务异常基类，携带对应 HTTP 状态码。
 */
public class DrBusinessException extends RuntimeException {

    private final HttpStatus status;

    public DrBusinessException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

package com.example.starter.dr;

import org.springframework.http.HttpStatus;

/**
 * 请求参数或业务前置条件不满足（400）。
 */
public class DrValidationException extends DrBusinessException {

    public DrValidationException(String message) {
        super(HttpStatus.BAD_REQUEST, message);
    }
}

package com.example.starter.dr;

import org.springframework.http.HttpStatus;

/**
 * 目标资源不存在（404）。
 */
public class DrNotFoundException extends DrBusinessException {

    public DrNotFoundException(String message) {
        super(HttpStatus.NOT_FOUND, message);
    }
}

package com.example.starter.dr;

import org.springframework.http.HttpStatus;

/**
 * 状态冲突：重复承诺、版本冲突、同键异参重放等（409）。
 */
public class DrConflictException extends DrBusinessException {

    public DrConflictException(String message) {
        super(HttpStatus.CONFLICT, message);
    }
}

